package com.studio.ai;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import android.content.SharedPreferences;import android.database.Cursor;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.provider.OpenableColumns;import android.view.Gravity;import android.view.View;import android.widget.*;import org.json.JSONArray;import org.json.JSONObject;import java.util.LinkedHashSet;import java.util.Locale;import java.util.Set;
public class MainActivity extends Activity{
 private LinearLayout root,content;private SharedPreferences prefs;private String project="",style="";private Runnable backAction;private static final int PICK_VIDEO=2001;private final int BG=Color.rgb(9,11,15),CARD=Color.rgb(19,23,30),MUTED=Color.rgb(151,160,174),GREEN=Color.rgb(124,255,178);private final String[] styles={"إعلانات الشركات","تجمعيات أنمي","TikTok","YouTube","رعب","أكشن","عام"};
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("studio",MODE_PRIVATE);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);home();}private int dp(float x){return Math.round(x*getResources().getDisplayMetrics().density);}private GradientDrawable bg(int c,float r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}private TextView tx(String s,float z,int c,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setTypeface(Typeface.create("sans",bold?Typeface.BOLD:Typeface.NORMAL));v.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);v.setTextDirection(View.TEXT_DIRECTION_RTL);v.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);v.setLineSpacing(0,1.12f);return v;}private Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextSize(16);b.setAllCaps(false);b.setTextColor(Color.rgb(5,20,13));b.setTypeface(null,Typeface.BOLD);b.setBackground(bg(GREEN,18));return b;}
 private void base(String title,String sub){ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.setBackgroundColor(BG);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.setBackgroundColor(BG);sc.addView(root,new ScrollView.LayoutParams(-1,-2));setContentView(sc);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(20),i.getSystemWindowInsetTop()+dp(14),dp(20),i.getSystemWindowInsetBottom()+dp(24));return i;});root.requestApplyInsets();TextView brand=tx("STUDIO  /  AI",12,GREEN,true);brand.setTextDirection(View.TEXT_DIRECTION_LTR);brand.setLetterSpacing(.16f);root.addView(brand);TextView t=tx(title,29,Color.WHITE,true);LinearLayout.LayoutParams tl=new LinearLayout.LayoutParams(-1,-2);tl.setMargins(0,dp(8),0,dp(4));root.addView(t,tl);TextView s=tx(sub,14,MUTED,false);LinearLayout.LayoutParams sl=new LinearLayout.LayoutParams(-1,-2);sl.setMargins(0,0,0,dp(22));root.addView(s,sl);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.addView(content);}private void back(String label,Runnable r){TextView b=tx("‹  "+label,15,GREEN,true);b.setPadding(0,dp(22),0,dp(18));root.addView(b);b.setOnClickListener(v->r.run());backAction=r;}private void card(String title,String sub,Runnable r){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setBackground(bg(CARD,18));c.setPadding(dp(18),dp(13),dp(18),dp(13));c.setMinimumHeight(dp(66));c.addView(tx(title,17,Color.WHITE,true));if(!sub.isEmpty())c.addView(tx(sub,13,MUTED,false));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));content.addView(c,lp);if(r!=null)c.setOnClickListener(v->r.run());}private void disabled(String a,String b){card(a,b,null);}
 private void home(){project="";style="";backAction=null;base("الاستوديو","مساحة عملك الخاصة للمونتاج والتعلّم من الأساليب.");Button add=btn("＋  إنشاء مشروع");content.addView(add,new LinearLayout.LayoutParams(-1,dp(58)));add.setOnClickListener(v->newProject());TextView h=tx("المشاريع الأخيرة",18,Color.WHITE,true);LinearLayout.LayoutParams hl=new LinearLayout.LayoutParams(-1,-2);hl.setMargins(0,dp(28),0,dp(12));content.addView(h,hl);Set<String> ps=prefs.getStringSet("projects",new LinkedHashSet<>());if(ps.isEmpty())content.addView(tx("لا توجد مشاريع بعد.",14,MUTED,false));else for(String p:ps){String[] x=p.split("\\|",2);String n=x[0],s=x.length>1?x[1]:"عام";card(n,s,()->workspace(n,s));}}
 private void newProject(){base("مشروع جديد","اكتب اسم المشروع ثم اختر قسمه.");EditText e=new EditText(this);e.setHint("مثال: إعلان مطعم العميل");e.setHintTextColor(MUTED);e.setTextColor(Color.WHITE);e.setTextDirection(View.TEXT_DIRECTION_RTL);e.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);e.setBackground(bg(CARD,18));e.setPadding(dp(18),0,dp(18),0);content.addView(e,new LinearLayout.LayoutParams(-1,dp(58)));Button n=btn("التالي  ←");content.addView(n,new LinearLayout.LayoutParams(-1,dp(56)));n.setOnClickListener(v->{String name=e.getText().toString().trim();if(name.isEmpty()){e.setError("اكتب اسم المشروع");return;}chooseStyle(name);});back("رجوع للرئيسية",this::home);}private void chooseStyle(String name){base("اختر أسلوب المشروع","كل قسم مستقل بمواده وتحليلاته وذاكرته.");for(String s:styles)card(s,"",()->saveProject(name,s));back("رجوع للرئيسية",this::home);}private void saveProject(String n,String s){Set<String> p=new LinkedHashSet<>(prefs.getStringSet("projects",new LinkedHashSet<>()));p.add(n+"|"+s);prefs.edit().putStringSet("projects",p).apply();workspace(n,s);}
 private void workspace(String n,String s){project=n;style=s;base(n,s+"  •  مساحة مشروع مستقلة");card("🎬  الفيديوهات","استيراد وتشغيل الفيديو",()->videos(n,s));card("🧪  التحليل البصري والزمني","الحركة • تغير الإطارات • مرشحات القص",()->analysisList(n,s));card("🎛  بصمة أسلوب المونتاج","الإيقاع • كثافة القص • الحركة • الطابع البصري",()->styleList(n,s));JSONObject mem=ShortTermMemory.load(prefs,n,s);String active=mem.optString("activeVideoName","");card("🧠  الذاكرة قصيرة المدى",active.isEmpty()?"لا يوجد سياق نشط بعد":"آخر فيديو نشط: "+active,()->memory(n,s));card("🗂  الأرشيف","مواد المشروع ونتائج التحليل",()->archive(n,s));disabled("💬  شات المشروع","سيستخدم هذه الذاكرة في دفعة الشات");disabled("✨  المؤثرات والانتقالات","موعد المكتبة في دفعتها");back("رجوع للرئيسية",this::home);}
 private String key(String n,String s){return"videos_"+Integer.toHexString((n+"|"+s).hashCode());}private JSONArray list(String n,String s){try{return new JSONArray(prefs.getString(key(n,s),"[]"));}catch(Exception e){return new JSONArray();}}private void save(String n,String s,JSONArray a){prefs.edit().putString(key(n,s),a.toString()).apply();}
 private void videos(String n,String s){project=n;style=s;base("فيديوهات المشروع",n+" • "+s);Button add=btn("＋  استيراد فيديو من الجوال");content.addView(add,new LinearLayout.LayoutParams(-1,dp(58)));add.setOnClickListener(v->pick());JSONArray a=list(n,s);if(a.length()==0)content.addView(tx("لا توجد فيديوهات حتى الآن.",14,MUTED,false));else for(int i=a.length()-1;i>=0;i--){JSONObject o=a.optJSONObject(i);if(o!=null)videoCard(o,n,s);}back("رجوع للمشروع",()->workspace(n,s));}private void videoCard(JSONObject o,String n,String s){String name=o.optString("name","فيديو"),uri=o.optString("uri","");JSONObject in=o.optJSONObject("inspection");String status=in==null?"لم يتم التحليل":"تحليل v"+in.optInt("analysisVersion",3);card("🎞  "+name,status,()->player(name,uri,n,s));}
 private void analysisList(String n,String s){base("التحليل البصري والزمني",n);JSONArray a=list(n,s);if(a.length()==0)content.addView(tx("أضف فيديو أولًا.",14,MUTED,false));for(int i=a.length()-1;i>=0;i--){JSONObject o=a.optJSONObject(i);if(o!=null)card(o.optString("name","فيديو"),o.optJSONObject("inspection")==null?"لم يُحلل":"افتح القياسات",()->analysisDetail(o,n,s));}back("رجوع للمشروع",()->workspace(n,s));}private void analysisDetail(JSONObject o,String n,String s){JSONObject x=o.optJSONObject("inspection");base("نتيجة التحليل",o.optString("name"));if(x!=null){JSONArray cuts=x.optJSONArray("cutCandidates");card("متوسط الحركة",x.optDouble("averageMotion")+"/100",null);card("متوسط التغير",x.optDouble("averageChange")+"/100",null);card("مرشحات القص",String.valueOf(cuts==null?0:cuts.length()),null);Button b=btn("↻ إعادة التحليل");content.addView(b,new LinearLayout.LayoutParams(-1,dp(54)));b.setOnClickListener(v->reanalyze(o,n,s));}back("رجوع للتحليل",()->analysisList(n,s));}
 private void styleList(String n,String s){base("بصمة أسلوب المونتاج",n);JSONArray a=list(n,s);for(int i=a.length()-1;i>=0;i--){JSONObject o=a.optJSONObject(i),in=o==null?null:o.optJSONObject("inspection"),st=in==null?null:in.optJSONObject("editingStyle");if(o!=null)card(o.optString("name","فيديو"),st==null?"أعد التحليل لإنشاء البصمة":"افتح البصمة",st==null?null:()->styleDetail(o,n,s));}back("رجوع للمشروع",()->workspace(n,s));}private void styleDetail(JSONObject o,String n,String s){JSONObject x=o.optJSONObject("inspection").optJSONObject("editingStyle");base("بصمة المونتاج",o.optString("name"));String info="الإيقاع: "+ar(x.optString("pace"))+"\nالقصات/دقيقة: "+x.optDouble("cutsPerMinute")+"\nمتوسط المقطع: "+x.optDouble("averageShotSeconds")+" ث\nالحركة: "+ar(x.optString("motionLevel"))+"\nالطاقة البصرية: "+ar(x.optString("visualEnergy"))+"\nالإضاءة: "+ar(x.optString("tone"))+"\nالألوان: "+ar(x.optString("colorCharacter"));card("القياسات",info,null);back("رجوع للبصمات",()->styleList(n,s));}
 private void memory(String n,String s){base("الذاكرة قصيرة المدى",n+" • "+s);JSONObject m=ShortTermMemory.load(prefs,n,s);String active=m.optString("activeVideoName","");card("السياق الحالي",active.isEmpty()?"لا يوجد فيديو نشط":"الفيديو النشط: "+active,null);JSONObject a=m.optJSONObject("latestAnalysis");if(a!=null){JSONObject st=a.optJSONObject("editingStyle");String summary="الحركة "+a.optDouble("averageMotion")+" • التغير "+a.optDouble("averageChange")+" • مرشحات القص "+a.optInt("cutCandidates");if(st!=null)summary+="\nالإيقاع "+ar(st.optString("pace"))+" • الحركة "+ar(st.optString("motionLevel"));card("آخر تحليل محفوظ في السياق",summary,null);}EditText note=new EditText(this);note.setHint("ملاحظة مؤقتة للمشروع، مثال: خل البداية أسرع");note.setHintTextColor(MUTED);note.setTextColor(Color.WHITE);note.setBackground(bg(CARD,18));note.setPadding(dp(16),dp(10),dp(16),dp(10));content.addView(note,new LinearLayout.LayoutParams(-1,dp(72)));Button add=btn("حفظ ملاحظة في الذاكرة");LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(52));ap.setMargins(0,dp(10),0,dp(14));content.addView(add,ap);add.setOnClickListener(v->{String t=note.getText().toString().trim();if(!t.isEmpty()){ShortTermMemory.addNote(prefs,n,s,t);memory(n,s);}});JSONArray notes=m.optJSONArray("notes");if(notes!=null)for(int i=notes.length()-1;i>=0;i--){JSONObject q=notes.optJSONObject(i);if(q!=null)card("ملاحظة",q.optString("text"),null);}Button clear=btn("مسح الذاكرة قصيرة المدى");content.addView(clear,new LinearLayout.LayoutParams(-1,dp(52)));clear.setOnClickListener(v->{ShortTermMemory.clear(prefs,n,s);memory(n,s);});TextView info=tx("هذه الذاكرة خاصة بهذا المشروع فقط، ومحدودة تلقائيًا حتى لا تكبر بلا نهاية. الذاكرة طويلة المدى تأتي في الدفعة السابعة.",13,MUTED,false);content.addView(info);back("رجوع للمشروع",()->workspace(n,s));}
 private String ar(String s){if("fast".equals(s))return"سريع";if("medium".equals(s))return"متوسط";if("slow".equals(s))return"هادئ";if("high".equals(s))return"مرتفع";if("low".equals(s))return"منخفض";if("dark".equals(s))return"داكن";if("bright".equals(s))return"مضيء";if("balanced".equals(s))return"متوازن";if("muted".equals(s))return"مطفأ";if("vivid".equals(s))return"حيوي";return s;}
 private void archive(String n,String s){base("أرشيف المشروع",n);JSONArray a=list(n,s);for(int i=a.length()-1;i>=0;i--){JSONObject o=a.optJSONObject(i);if(o!=null)videoCard(o,n,s);}back("رجوع للمشروع",()->workspace(n,s));}private void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("video/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,PICK_VIDEO);}
 @Override protected void onActivityResult(int rc,int result,Intent data){super.onActivityResult(rc,result,data);if(rc!=PICK_VIDEO||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}JSONArray a=list(project,style);for(int i=0;i<a.length();i++){JSONObject old=a.optJSONObject(i);if(old!=null&&uri.toString().equals(old.optString("uri"))){videos(project,style);return;}}JSONObject o=new JSONObject();try{o.put("name",displayName(uri));o.put("uri",uri.toString());o.put("added",System.currentTimeMillis());a.put(o);save(project,style,a);}catch(Exception e){return;}analyzeAsync(uri,o,project,style);}
 private void analyzeAsync(Uri uri,JSONObject target,String n,String s){Toast.makeText(this,"جارٍ التحليل…",Toast.LENGTH_SHORT).show();new Thread(()->{try{JSONObject inspection=VideoInspector.inspect(this,uri);target.put("inspection",inspection);JSONArray latest=list(n,s);String u=target.optString("uri");JSONObject savedTarget=target;for(int i=0;i<latest.length();i++){JSONObject item=latest.optJSONObject(i);if(item!=null&&u.equals(item.optString("uri"))){item.put("inspection",inspection);savedTarget=item;break;}}save(n,s,latest);ShortTermMemory.rememberVideo(prefs,n,s,savedTarget);runOnUiThread(()->{Toast.makeText(this,"اكتمل التحليل وتم تحديث الذاكرة",Toast.LENGTH_SHORT).show();videos(n,s);});}catch(Exception e){runOnUiThread(()->{Toast.makeText(this,"تعذر تحليل الفيديو",Toast.LENGTH_LONG).show();videos(n,s);});}}).start();}private void reanalyze(JSONObject o,String n,String s){String u=o.optString("uri","");if(!u.isEmpty())analyzeAsync(Uri.parse(u),o,n,s);}private String displayName(Uri u){Cursor c=null;try{c=getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null);if(c!=null&&c.moveToFirst()){int x=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(x>=0)return c.getString(x);}}catch(Exception ignored){}finally{if(c!=null)c.close();}return"فيديو";}
 private void player(String file,String uri,String n,String s){ShortTermMemory.rememberOpenedVideo(prefs,n,s,file,uri);base("مشغل الفيديو",file);FrameLayout f=new FrameLayout(this);f.setBackground(bg(Color.BLACK,18));VideoView vv=new VideoView(this);f.addView(vv,new FrameLayout.LayoutParams(-1,dp(230)));content.addView(f,new LinearLayout.LayoutParams(-1,dp(238)));MediaController mc=new MediaController(this);mc.setAnchorView(vv);vv.setMediaController(mc);vv.setVideoURI(Uri.parse(uri));vv.setOnPreparedListener(mp->{mp.setLooping(false);vv.start();});back("رجوع للفيديوهات",()->videos(n,s));}private String format(long ms){long total=Math.max(0,ms)/1000,h=total/3600,m=(total%3600)/60,sec=total%60;return h>0?String.format(Locale.US,"%d:%02d:%02d",h,m,sec):String.format(Locale.US,"%02d:%02d",m,sec);}@Override public void onBackPressed(){if(backAction!=null)backAction.run();else home();}
}